pro_features=['Everything in Plus','Export to Xmind and MindNode','Share links to your maps','The most capable AI model']
particles=''.join(f'<img src="../assets/particle-{["node","branch","spark"][i%3]}-{["white","gray"][i%2]}-{20 if i%2==0 else 15}.imageset/particle-{["node","branch","spark"][i%3]}-{["white","gray"][i%2]}-{20 if i%2==0 else 15}.svg" style="left:{6+(i*17)%84}%;top:{16+(i*23)%50}%;width:{20 if i%2==0 else 15}px;animation-delay:-{i%7}s" alt="">' for i in range(10))
content='<div class="top paywall-close">'+btn('xmark','Close','02-create','mn-close')+'</div><section class="paywall-content"><img class="paywall-logo" src="'+logo+'" alt="Minor"><h1 class="title-3" data-plan-title>Minor Plus</h1><div class="mn-features" aria-live="polite">'+''.join('<div class="mn-feature">'+ico('checkmark')+'<span>'+x+'</span></div>' for x in plus_features)+'</div><div class="particles particle-band" aria-hidden="true">'+particles+'</div><div class="paywall-controls"><div class="mn-seg" data-segment="period"><span class="thumb"></span><button aria-selected="true">Monthly</button><button aria-selected="false">Yearly</button></div><div class="mn-seg" data-segment="plan"><span class="thumb"></span><button aria-selected="true">Plus</button><button class="pro" aria-selected="false">PRO</button></div><button class="mn-buy" data-action="purchase">$9.99</button><div class="paywall-legal"><div class="mn-legal"><button data-action="terms">Terms &amp; Conditions</button><span>|</span><button data-action="privacy">Privacy Policy</button></div><button class="restore-link caption" data-action="restore">Restore Purchases</button></div></div></section>'
band='<div class="particles particle-band" aria-hidden="true">'+particles+'</div>'
