# A reviewable native-style sign-in composition. Authentication itself is not connected.
signin=glow+f'<section class="signin-intro"><div class="mn-halo"><img src="{logo}" alt="Minor"></div><h1 class="title-2">Save Your Maps</h1><p class="subhead secondary">Sign in to keep your maps<br>on all your devices.</p></section><footer class="signin-actions"><button class="apple-signin" data-action="apple-signin"><img src="../assets/apple-sign-in-logo.svg" width="15" height="19" alt=""><span>Sign in with Apple</span></button><a class="not-now body-lg secondary" href="01-home.html">Not Now</a><p class="caption tertiary">By continuing you agree to the <button data-action="terms">Terms</button> and <button data-action="privacy">Privacy Policy</button>.</p></footer>'
screen('10-sign-in','Save Your Maps',signin,'sign-in','Account')
# Compact illustrations made with existing MindNode / Connector / SourceTile.
def mini_map(kind):
    branch='Pricing' if kind=='expand' else 'Mind Map'
    if kind=='expand':
        return '<div class="intro-map mn-canvas"><svg class="mn-links" viewBox="0 0 360 280" aria-hidden="true">'+''.join(f'<path class="mn-link ghost" d="M161 140 C188 140 188 {y} 217 {y}"/>' for y in [90,140,190])+'</svg><span class="mn-node lv1 b-lilac is-generating">'+ico('sparkles')+branch+'</span>'+''.join(f'<span class="mn-ghost" style="left:217px;top:{y-12}px;width:{w}px"></span>' for y,w in [(90,92),(140,74),(190,108)])+'</div>'
    return '<div class="intro-map mn-canvas"><svg class="mn-links" viewBox="0 0 360 280" aria-hidden="true">'+''.join(f'<path class="mn-link l1 s-{c}" d="M148 140 C176 140 176 {y} 204 {y}"/>' for c,y in [('mint',64),('sky',140),('lilac',216)])+'</svg><span class="mn-node root">Mind<br>Map</span>'+''.join(f'<span class="mn-node lv1 b-{c}" style="left:204px;top:{y-22}px">{t}</span>' for c,y,t in [('mint',64,'Audience'),('sky',140,'New idea'),('lilac',216,'Pricing')])+'</div>'
for i,title,sub in [(1,'Think in Maps','Type a topic and Minor builds a mind map in seconds.'),(2,'Start From Anything','Drop a PDF, paste a link or a YouTube video, or just talk.'),(3,'Go Deeper With AI','Tap any idea and Minor expands it into new branches.')]:
    if i==2:
        art='<div class="source-fan">'+''.join(f'<div class="mn-source fan-tile tile-{n}">{ico(icon)}<span class="t">{label}</span><span class="s">{desc}</span></div>' for n,(label,desc,icon) in enumerate([sources[1],sources[3],sources[4]]))+'</div>'
    else:art=mini_map('expand' if i==3 else 'tree')
    content='<header class="top onboarding-top"><a class="text-button" href="10-sign-in.html">Skip</a></header>'+glow+'<div class="onboarding-art">'+art+'</div><section class="onboarding-copy"><h1 class="title-2">'+title+'</h1><p class="subhead secondary">'+sub+'</p></section><footer class="onboarding-bottom"><div class="page-dots" aria-label="Step '+str(i)+' of 3">'+''.join(f'<a class="{"active" if n==i else ""}" href="11-onboarding-{n}.html" aria-label="Step {n}" {"aria-current=step" if n==i else ""}><span></span></a>' for n in [1,2,3])+'</div><a class="primary-button" href="'+('10-sign-in' if i==3 else '11-onboarding-'+str(i+1))+'.html">Continue</a></footer>'
    screen('11-onboarding-'+str(i),title,content,'onboarding-screen','Onboarding')
# Settings stays in a sheet and uses native-neutral groups.
def settings():
    head=sheethead('Settings').replace('04-editor-node-selected.html','07-your-maps.html')
    account='<section class="section"><h2 class="mn-overline">ACCOUNT</h2><div class="mn-group">'+row('Apple ID','globe','alex@icloud.com',extra='data-action="account"')+row('Subscription','star.fill','Minor Plus · Renews Nov 2',extra='data-action="subscription"')+row('Restore Purchases','arrow.uturn.backward',extra='data-action="restore"')+'</div></section>'
    premium='<section class="section"><h2 class="mn-overline">PREMIUM</h2><div class="mn-group">'+row('Upgrade to PRO','star.fill','','09-paywall',extra='')+row('Chat Themes','paintbrush.fill',extra='data-action="themes" aria-expanded="false"')+'</div><div class="settings-swatches" hidden>'+''.join(f'<button class="mn-swatch" data-theme-choice="{t.lower()}" aria-label="{t}" aria-pressed="{str(t=="Classic").lower()}"><i data-theme="{t.lower()}"></i><span>{t}</span></button>' for t in ['Classic','Vio','Aqua','Rosa','Cosmos','Flam'])+'</div></section>'
    general='<section class="section"><h2 class="mn-overline">GENERAL</h2><div class="mn-group">'+row('App Language','globe','English',extra='data-action="language"')+row('Privacy Policy','doc.text',extra='data-action="privacy"')+row('Terms of Use','doc.text',extra='data-action="terms"')+'</div></section>'
    ending='<section class="section"><div class="mn-group">'+row('Log Out','rectangle.portrait.and.arrow.right','','10-sign-in')+'</div></section><section class="section"><div class="mn-group">'+row('Delete Account','trash','','12-settings-delete',True)+'</div></section><footer class="settings-version caption tertiary"><span>By Neuvra</span><span>Version 2.0</span></footer>'
    return '<section class="mn-sheet settings-sheet">'+head+'<div class="settings-scroll">'+account+premium+general+ending+'</div></section>'
backdrop='<img class="mn-watermark watermark" src="'+logo+'" alt="">'+glow
screen('12-settings','Settings',backdrop+settings(),'settings-screen','Settings')
alert='<div class="account-alert-overlay"><section class="account-alert" role="alertdialog" aria-modal="true" aria-labelledby="delete-title" aria-describedby="delete-description"><div class="alert-copy"><h2 class="headline" id="delete-title">Delete your account?</h2><p class="footnote" id="delete-description">Your maps and chats will be permanently deleted. This can’t be undone.</p></div><div class="alert-actions"><a class="body-lg" href="12-settings.html">Cancel</a><button class="body-lg danger" data-action="confirm-delete-account">Delete Account</button></div></section></div>'
screen('12-settings-delete','Settings · Delete Account',backdrop+'<div inert>'+settings()+'</div>'+alert,'settings-screen delete-account','Settings')
screen('13-launch','Launch',f'<img class="mn-watermark watermark" src="{logo}" alt="Minor">','launch-screen','Launch',chrome=False)
# Explicit Expand state supports the requested third App Store screenshot.
expand_content=editor('selected')
expand_content=expand_content.replace('b-lilac map-node is-selected','b-lilac map-node is-selected is-generating')
# Existing leaves become ghost children in this visual state, retaining exact connector geometry.
expand_content=re.sub(r'<button class="mn-node leaf b-lilac map-node" style="([^"]+)"[^>]*>[^<]+</button>',lambda m:'<span class="mn-ghost map-expanding-ghost" style="'+m.group(1)+'"></span>',expand_content)
expand_content=expand_content.replace('mn-link l2 s-lilac-line','mn-link ghost')
screen('04-editor-expanding','Launch plan · Expanding',expand_content,'editor expanding','Editor')
